"Vegan": "نباتي صرف",
"Leave out": "شيل",
"Dairy": "الألبان",
"Eggs": "البيض",
"Fish and seafood": "السمك والمأكولات البحرية",
"Nuts": "المكسرات",
"Gluten": "الجلوتين",
"Protein powder": "بروتين باودر",
